-- Founder-led Customer Success (CLAUDE.md section 173). Run ONE statement per message in D1 Studio.
CREATE TABLE IF NOT EXISTS cs_customers (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, first_name TEXT NOT NULL DEFAULT '', company TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active', paused_reason TEXT NOT NULL DEFAULT '', enrolled_by TEXT NOT NULL DEFAULT 'auto', enrolled_at INTEGER NOT NULL DEFAULT (unixepoch()), last_run_at INTEGER NOT NULL DEFAULT 0, interests_json TEXT NOT NULL DEFAULT '', rec_override_json TEXT NOT NULL DEFAULT '', last_sender TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS cs_prefs (email_hash TEXT PRIMARY KEY, recs INTEGER NOT NULL DEFAULT 1, products INTEGER NOT NULL DEFAULT 1, founder INTEGER NOT NULL DEFAULT 1, education INTEGER NOT NULL DEFAULT 1, offers INTEGER NOT NULL DEFAULT 1, frequency TEXT NOT NULL DEFAULT 'normal', countries TEXT NOT NULL DEFAULT '', industries TEXT NOT NULL DEFAULT '', unsub_all INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS cs_scheduled (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL, template_key TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '-', status TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', sender TEXT NOT NULL DEFAULT '', provider_id TEXT NOT NULL DEFAULT '', attempts INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL DEFAULT (unixepoch()), sent_at INTEGER, updated_at INTEGER NOT NULL DEFAULT (unixepoch()), UNIQUE (customer_id, template_key, reference));
CREATE INDEX IF NOT EXISTS idx_cs_scheduled_customer ON cs_scheduled (customer_id, status);
CREATE INDEX IF NOT EXISTS idx_cs_scheduled_provider ON cs_scheduled (provider_id);
CREATE TABLE IF NOT EXISTS cs_feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, reference TEXT NOT NULL UNIQUE, email TEXT NOT NULL, order_id TEXT NOT NULL DEFAULT '', satisfaction INTEGER NOT NULL, product_experience TEXT NOT NULL DEFAULT '', worked_well TEXT NOT NULL DEFAULT '', improve TEXT NOT NULL DEFAULT '', comments TEXT NOT NULL DEFAULT '', wants_help INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'new', note TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS cs_events (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL, kind TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', actor TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS idx_cs_events_customer ON cs_events (customer_id, created_at);
CREATE TABLE IF NOT EXISTS cs_updates (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, url TEXT NOT NULL DEFAULT '', approved_by TEXT NOT NULL, approved_at INTEGER NOT NULL DEFAULT (unixepoch()), recipients INTEGER NOT NULL DEFAULT 0);
